parameters.jsCode:
// ============================================================
// Validate & Extract Session Data
// Reads session state and the submitted question from MongoDB.
// Learner sends only: session_id, learner_id, question_id, answer.
// ============================================================

const body = $('Webhook - Submit Answer').first().json.body || {};

if (!body.session_id)
  throw new Error('Missing session_id');
if (!body.learner_id)
  throw new Error('Missing learner_id');
if (!body.question_id)
  throw new Error('Missing question_id');
if (body.answer === undefined || body.answer === null)
  throw new Error('Missing answer');

// ------------------------------------------------------------
// Read latest session update
// ------------------------------------------------------------
let sessionUpdateDoc = null;
try {
  const raw = $('MongoDB - Fetch Session State').first().json;
  if (raw && raw.updated_session) {
    sessionUpdateDoc = raw;
  }
} catch (e) {}

// ------------------------------------------------------------
// Fallback to initial session
// ------------------------------------------------------------
let initialSessionDoc = null;
try {
  const raw = $('MongoDB - Fetch Initial Session').first().json;
  if (raw && raw.session_id) {
    initialSessionDoc = raw;
  }
} catch (e) {}

// ------------------------------------------------------------
        // Read submitted/current question
        // IMPORTANT:
        // Fetch Current Question intentionally queries ONLY by session_id.
        // Some MongoDB/n8n versions are unreliable with complex $or
        // queries in the MongoDB node. We therefore retrieve the session's
        // question documents and perform the exact question_id match here.
        // This supports both the new root question_id field and legacy
        // current_question.question_id documents.
        // ------------------------------------------------------------
        let questionDoc = null;
        try {
          const questionItems = $('MongoDB - Fetch Current Question').all();

          const candidates = questionItems
            .map(item => item?.json || {})
            .filter(doc => doc && doc.current_question);

          const requestedQuestionId = String(body.question_id).trim();

          questionDoc =
            candidates.find(doc =>
              String(doc.question_id || '').trim() === requestedQuestionId
            ) ||
            candidates.find(doc =>
              String(doc.current_question?.question_id || '').trim() === requestedQuestionId
            ) ||
            null;
        } catch (e) {
          console.log('Fetch Current Question read error:', e.message);
          questionDoc = null;
        }

// ------------------------------------------------------------
// Resolve session state
// ------------------------------------------------------------
let sessionState;

if (sessionUpdateDoc && sessionUpdateDoc.updated_session) {
  sessionState = sessionUpdateDoc.updated_session;
} else if (initialSessionDoc && initialSessionDoc.session_id) {
  sessionState = initialSessionDoc;
} else {
  throw new Error(
    `No session state found in MongoDB for session_id: ${body.session_id}. ` +
    `Ensure start-session was called first and the session was saved correctly.`
  );
}

// ------------------------------------------------------------
// Validate question document
// ------------------------------------------------------------
if (!questionDoc || !questionDoc.current_question) {
  let fetchedCount = 0;
  try {
    fetchedCount = $('MongoDB - Fetch Current Question').all().length;
  } catch (e) {}

  throw new Error(
    `No question found in MongoDB for session_id=${body.session_id}, ` +
    `question_id=${body.question_id}. ` +
    `Fetch Current Question returned ${fetchedCount} document(s) for this session. ` +
    `Check that MongoDB - Save Question / Save Next Question inserts into ` +
    `ame_questions and that session_id is stored identically.`
  );
}

const currentQuestion = questionDoc.current_question;

// ------------------------------------------------------------
// Verify root and nested IDs when available
// ------------------------------------------------------------
const storedQuestionId = String(
  questionDoc.question_id ||
  currentQuestion.question_id ||
  ''
).trim();

if (!storedQuestionId) {
  throw new Error(
    `Question document exists but has no question_id. ` +
    `session_id=${body.session_id}`
  );
}

if (storedQuestionId !== String(body.question_id).trim()) {
  throw new Error(
    `question_id mismatch: request has ${body.question_id} ` +
    `but MongoDB has ${storedQuestionId}`
  );
}

if (
  currentQuestion.question_id &&
  String(currentQuestion.question_id).trim() !== String(body.question_id).trim()
) {
  throw new Error(
    `Nested question_id mismatch: request has ${body.question_id} ` +
    `but current_question has ${currentQuestion.question_id}`
  );
}

// Optional but useful protection against submitting a question for another learner.
if (
  questionDoc.learner_id &&
  String(questionDoc.learner_id) !== String(body.learner_id)
) {
  throw new Error(
    `learner_id mismatch: request has ${body.learner_id} ` +
    `but MongoDB question belongs to ${questionDoc.learner_id}`
  );
}

// ------------------------------------------------------------
// Reconstruct sessionData — downstream contract unchanged
// ------------------------------------------------------------
const sessionData = {
  session_id:                  sessionState.session_id || body.session_id,
  learner_id:                  sessionState.learner_id || body.learner_id,
  mastery_profile:             sessionState.mastery_profile,
  selected_topic:              sessionState.selected_topic,
  all_topics:                  sessionState.all_topics || [],
  remaining_topics:            sessionState.remaining_topics || [],
  current_difficulty:          sessionState.current_difficulty,
  question_number:             sessionState.question_number || 1,
  mastery_score:               sessionState.mastery_score || 0,
  total_questions_asked:       sessionState.total_questions_asked || 0,
  correct_answers:             sessionState.correct_answers || 0,
  consecutive_correct:        sessionState.consecutive_correct || 0,
  consecutive_wrong:          sessionState.consecutive_wrong || 0,
  session_history:             sessionState.session_history || [],
  topic_scores:                sessionState.topic_scores || {},
  mastery_threshold:           sessionState.mastery_threshold || 85,
  max_questions_per_topic:     sessionState.max_questions_per_topic || 10,
  session_started_at:          sessionState.session_started_at || new Date().toISOString(),
  remediation_mode:            sessionState.remediation_mode || false,
  remediation_questions:       sessionState.remediation_questions || 0,
  max_remediation_questions:   sessionState.max_remediation_questions || 6
};

return [{
  json: {
    session_id:       body.session_id,
    learner_id:       body.learner_id,
    question_id:      body.question_id,
    submitted_answer: body.answer,
    submitted_at:     new Date().toISOString(),
    sessionData,
    questionData:     { current_question: currentQuestion },
    question:         currentQuestion,
    submittedAnswer:  body.answer
  }
}];

const data            = $input.first().json;
const question        = data.question;
const submittedAnswer = data.submittedAnswer;

// ── Sandbox execution result (code_completion / coding_challenge only) ──
// Populated upstream by "Parse Sandbox Execution Result" when the
// question required real Java compilation/execution. Null for MCQ.
const sandbox = data.sandbox_result || null;
const sandboxBlock = (sandbox && sandbox.attempted && sandbox.status !== 'sandbox_unavailable')
  ? `\nSANDBOX EXECUTION RESULT (actual compiler/runtime output — trust this over your own mental simulation of the code):\nCompiled: ${sandbox.compiled}\nStatus: ${sandbox.status}\n${sandbox.compile_output ? `Compile Errors:\n${sandbox.compile_output}\n` : ''}${sandbox.stdout ? `Program Output (stdout):\n${sandbox.stdout}\n` : ''}${sandbox.stderr ? `Runtime Errors (stderr):\n${sandbox.stderr}\n` : ''}\nIf the code failed to compile or crashed, it CANNOT be scored as fully correct even if the approach looks reasonable.\n`
  : '';

let promptText = null;
let isMcq = false;

if (question.question_type === 'mcq') {
  isMcq = true;
} else {
  promptText = `You are an expert Java programming evaluator. Evaluate this learner's Java answer.

QUESTION:
Topic: ${question.topic}
Difficulty: ${question.difficulty}
Type: ${question.question_type}
Question: ${question.question_text}
${question.code_snippet && question.code_snippet !== 'null' ? `\nCode Provided:\n${question.code_snippet}` : ''}

EXPECTED ANSWER: ${question.correct_answer}
EVALUATION CRITERIA: ${question.evaluation_criteria}
LEARNER ANSWER: ${submittedAnswer}
${sandboxBlock}

IMPORTANT: Respond with ONLY a valid JSON object. No explanation, no markdown, no extra text. Just raw JSON.

{
  "is_correct": <true or false>,
  "correctness_score": <number 0-100>,
  "evaluation_summary": "<1-2 sentence summary>",
  "what_is_correct": "<what the learner got right>",
  "what_is_wrong": "<what was wrong, or Nothing if fully correct>",
  "key_concept_understood": <true or false>,
  "partial_credit": <true or false>
}`;
}

const ollamaPayload = promptText ? {
  model: "gemma4:latest",
  format: "json",
  prompt: promptText,
  stream: false,
  options: { temperature: 0.1, num_predict: 600, num_ctx: 3072, keep_alive: '10m' }
} : null;

return [{ json: {
  ...data,
  evaluationPrompt: promptText,
  is_mcq:           isMcq,
  ollama_payload:   ollamaPayload
}}];

const data      = $input.first().json;
const correct   = String(data.question.correct_answer).trim().toUpperCase();
const submitted = String(data.submittedAnswer).trim().toUpperCase();
const isCorrect = correct === submitted;

return [{ json: {
  ...data,
