const evalResult = safeObject(data.evaluation_result);
const isCorrect  = evalResult.is_correct ?? false;

// ── Partial Correct + Weak Concepts ───────────────────────────
const isPartialCorrect = data.is_partial_correct || false;

const currentWeakConcepts = safeArray(data.weak_concepts);
const sessionHistory      = safeArray(session.session_history);

const lastEntry     = sessionHistory.length > 0
  ? sessionHistory[sessionHistory.length - 1]
  : null;

const lastWeakConc  = lastEntry
  ? safeArray(lastEntry.weak_concepts)
  : [];

const weakConcepts =
  currentWeakConcepts.length > 0
    ? currentWeakConcepts
    : lastWeakConc;

const hasWeakConcepts = weakConcepts.length > 0;

// ── Remediation State ─────────────────────────────────────────
const isRemediationMode    = session.remediation_mode || false;
const remediationQuestions = session.remediation_questions || 0;

const knowledgeGaps  = safeArray(profile.knowledge_gaps);

const topicDetails =
  knowledgeGaps.find(g => g.topic === topic) ?? {};

const misconceptions =
  safeArray(topicDetails.misconceptions);

const errorPatterns =
  safeArray(
    topicDetails.error_patterns ||
    topicDetails.observed_error_patterns ||
    []
  );

const askedQuestions =
  sessionHistory
    .map(h => h.question_text)
    .filter(Boolean);

const avoidSection =
  askedQuestions.length > 0
    ? `\nNEVER repeat these already-asked questions:\n${askedQuestions.slice(-8).join('\n')}`
    : '';

const topicScores   = safeObject(session.topic_scores);
const topicScoreObj = safeObject(topicScores[topic]);

const masteryScore =
  topicScoreObj.mastery_score ?? 0;

const questionsAsked =
  topicScoreObj.questions_asked ?? 0;

const consecutiveCorrect =
  session.consecutive_correct ?? 0;

const consecutiveWrong =
  session.consecutive_wrong ?? 0;

// ── Bloom's Taxonomy Levels ──────────────────────────────────
const bloomsLevels = {

  L1: {
    name: "Remembering (Bloom's L1)",
    difficulty: 'easy',
    question_type: 'mcq',
    instruction:
      "Generate an MCQ testing RECALL of facts, keywords, and syntax. 4 options A-D."
  },

  L2: {
    name: "Understanding (Bloom's L2)",
    difficulty: 'easy',
    question_type: 'mcq',
    instruction:
      "Generate an MCQ testing UNDERSTANDING of concepts. 4 options A-D."
  },

  L3: {
    name: "Applying (Bloom's L3)",
    difficulty: 'medium',
    question_type: 'code_completion',
    instruction:
      "Generate a Java CODE COMPLETION task with a code snippet."
  },

  L4: {
    name: "Analyzing (Bloom's L4)",
    difficulty: 'medium',
    question_type: 'code_tracing',
    instruction:
      "Generate a Java CODE TRACING problem where learner predicts execution/output."
  },

  L5: {
    name: "Evaluating (Bloom's L5)",
    difficulty: 'hard',
    question_type: 'debugging',
    instruction:
      "Generate a Java DEBUGGING challenge with intentional bugs."
  },

  L6: {
    name: "Creating (Bloom's L6)",
    difficulty: 'hard',
    question_type: 'coding_challenge',
    instruction:
      "Generate a Java CODING CHALLENGE requiring full implementation."
  }
};

function getDifficultyLevel(diff) {

  if (diff === 'easy')   return 'L1';
  if (diff === 'medium') return 'L3';
  if (diff === 'hard')   return 'L5';

  return 'L1';
}

function getNextBloomsLevel(
  currentDiff,
  isCorrect,
  consecCorrect,
  consecWrong,
  isPartial
) {

  const currentLevel =
    getDifficultyLevel(currentDiff);

  const levelOrder =
    ['L1','L2','L3','L4','L5','L6'];

  const currentIdx =
    levelOrder.indexOf(currentLevel);

  if (isCorrect) {

    // Move upward after 2 consecutive correct answers
    if (
      consecCorrect >= 2 &&
      currentIdx < levelOrder.length - 1
    ) {
      return levelOrder[currentIdx + 1];
    }

    return currentLevel;

  } else if (isPartial) {

    // Maintain same level for partial understanding
    return currentLevel;

  } else {

    // Step downward after incorrect answer
    if (
      consecWrong >= 1 &&
      currentIdx > 0
    ) {
      return levelOrder[currentIdx - 1];
    }

    return currentLevel;
  }
}

let promptText;
let nextDiff;

const misconceptionNote =
  misconceptions.length > 0
    ? `\nKnown misconceptions: ${misconceptions.slice(0,3).join(', ')}`
    : '';

const errorNote =
  errorPatterns.length > 0
    ? `\nError patterns: ${errorPatterns.slice(0,3).join(', ')}`
    : '';

// ── REMEDIATION MODE ──────────────────────────────────────────
if (isRemediationMode) {

  // ── VALIDATION RULE: Context-aware remediation type selection ─
  // Determine what the learner was doing BEFORE entering remediation
  // by reading the last few history entries' difficulty levels.
  // If learner was solving hard/medium problems and is partial-correct,
  // NEVER drop to recall MCQ — preserve conceptual continuity.

  const prevDifficulties = sessionHistory
    .slice(-3)
    .map(h => h.difficulty)
    .filter(Boolean);

  const wasSolvingHard   = prevDifficulties.includes('hard');
  const wasSolvingMedium = prevDifficulties.includes('medium') || wasSolvingHard;

  // CRITICAL VALIDATION:
  // If learner was at hard/medium AND had partial credit
  // → analytical remediation (NEVER recall MCQ)
  const needsAnalyticalRemediation = (
    (wasSolvingHard || wasSolvingMedium) && isPartialCorrect
  );

  // Context-aware question type selection
  // needsAnalyticalRemediation → code_tracing or code_completion always
  // Coming from easy + fully wrong → allowed to use structured MCQ briefly
  let remQuestionType, remBloomsLevel, remDifficulty;

  if (needsAnalyticalRemediation) {
    // Learner was doing hard/medium and has partial understanding
    // Preserve cognitive level — use analytical question types
    remDifficulty   = wasSolvingHard ? 'medium' : 'medium';
    remBloomsLevel  = "Analyzing (Bloom's L4) - REMEDIATION";
    remQuestionType = remediationQuestions < 3 ? 'code_tracing' : 'code_completion';

  } else {
    // Learner was at easy level or fully wrong at all levels
    // Allow gentle scaffolding: structured MCQ → code_tracing progression
    remDifficulty   = remediationQuestions < 2 ? 'easy' : 'medium';
    remBloomsLevel  = remediationQuestions < 2
      ? "Understanding (Bloom's L2) - REMEDIATION"
      : "Analyzing (Bloom's L4) - REMEDIATION";
    // Even for easy path: use MCQ only for first 1 question, then tracing
    remQuestionType = remediationQuestions < 1 ? 'mcq' : 'code_tracing';
  }

  const remConceptFocus =
    hasWeakConcepts
      ? `\nFOCUS specifically on these weak areas identified from the learner's last answer:\n${weakConcepts.slice(0,4).join('\n')}`
      : '';

  // Build remediation-specific instruction that preserves concept continuity
  let remInstructionDetail;

  if (needsAnalyticalRemediation) {
    remInstructionDetail = `
REMEDIATION TYPE: Analytical Scaffolded Remediation
REASON: Learner was solving ${wasSolvingHard ? 'hard' : 'medium'}-difficulty problems and showed partial understanding.

DO NOT generate:
- Simple recall questions ("What is the purpose of X?")
- Terminology-only MCQs
- Beginner-level definition questions

INSTEAD generate one of:
- Guided code execution tracing (trace through recursive calls step by step)
- Scaffolded code analysis (partially completed recursive logic to analyze)
- Structured code completion (fill in the specific missing logic related to the weak concept)
- Identify incorrect recursive branch or base condition error
- Fix a broken recursion structure that matches the learner's weak concept

CONCEPTUAL CONTINUITY RULE:
The question MUST stay connected to the learner's previous work.
If learner was working on recursion → generate recursion tracing.
If learner was working on sorting → generate sorting trace.
If learner was working on data structures → generate structural analysis.
NEVER jump to an unrelated simpler topic.`;
  } else {
    remInstructionDetail = `
REMEDIATION TYPE: Gentle Scaffolded Support
REASON: Learner needs foundational reinforcement.

Generate a guided analytical question:
- Use simple but complete Java code snippet
- Focus on the specific weak concept identified
- Include execution tracing elements
- Reinforce the concept step by step
DO NOT generate pure terminology recall questions.`;
  }

  promptText = `You are an expert adaptive Java tutor.

Generate EXACTLY ONE remediation question.

STRICT RULES:
- difficulty MUST be exactly "${remDifficulty}"
- blooms_level MUST be exactly "${remBloomsLevel}"
- question_type MUST be exactly "${remQuestionType}"
- Return ONLY valid JSON
- No markdown
- No explanations outside JSON
- Ensure JSON is COMPLETE and properly closed

IMPORTANT MCQ RULES (only if question_type is mcq):
- options MUST be: { "A":"...", "B":"...", "C":"...", "D":"..." }
- correct_answer MUST contain ONLY: "A", "B", "C", or "D"
- NEVER place explanations, reasoning, or sentences inside correct_answer

IMPORTANT NON-MCQ RULES (for code_tracing, code_completion, debugging):
- options MUST be null
- correct_answer should contain: actual output, expected code, or null
- evaluation_criteria must explain how the answer will be evaluated
${remInstructionDetail}

TOPIC: ${topic}
MISCONCEPTIONS:${misconceptionNote}
ERRORS:${errorNote}
${remConceptFocus}

Generate REAL Java content only targeting the specific weak concepts above.
Maintain conceptual continuity with the learner's previous problem-solving work.

Return ONLY valid JSON.`;

  nextDiff = remDifficulty;

} else {

  // ── NORMAL ADAPTIVE FLOW ───────────────────────────────────

  const nextLevel = getNextBloomsLevel(
    difficulty,
    isCorrect,
    consecutiveCorrect,
    consecutiveWrong,
    isPartialCorrect
  );

  const bloom = bloomsLevels[nextLevel];

  nextDiff = bloom.difficulty;

  let conceptFocusSection = '';

  if (hasWeakConcepts && !isCorrect) {

    conceptFocusSection = `
CONCEPT-LEVEL REMEDIATION REQUIRED:

The learner's last answer revealed these weak concepts:

${weakConcepts.slice(0,4).map((c,i) =>
  `${i+1}. ${c}`).join('\n')}

Do NOT generate a generic ${topic} question.
Target these specific weak concepts directly.
Use a different angle than previous questions.`;

  } else if (hasWeakConcepts && isPartialCorrect) {

    conceptFocusSection = `
PARTIAL UNDERSTANDING DETECTED:

Focus on these gaps:

${weakConcepts.slice(0,3).map((c,i) =>
  `${i+1}. ${c}`).join('\n')}

Maintain current cognitive level.
Deepen conceptual understanding.
Do NOT repeat previous question structure.`;
  }

  let adaptiveInstruction;

  if (isCorrect) {

    adaptiveInstruction =
      `Learner answered CORRECTLY (${consecutiveCorrect} consecutive correct answers).

Move toward ${bloom.name}.
Generate a MORE CHALLENGING question.`;

  } else if (isPartialCorrect) {

    adaptiveInstruction =
      `Learner gave a PARTIALLY CORRECT answer.

Maintain current Bloom level:
${bloom.name}

Target the weak concepts identified above.
Do NOT drop difficulty unnecessarily.`;

  } else {

    adaptiveInstruction =
      `Learner answered INCORRECTLY.

Provide scaffolded support using:
${bloom.name}

Keep same concept but use a different angle.
Do NOT repeat the same question.`;
  }

  // ✅ FIXED:
  // Includes code_tracing now

  let correctAnswerRule = '';

  if (
    [
      'coding_challenge',
      'debugging',
      'code_completion',
      'code_tracing'
    ].includes(bloom.question_type)
  ) {

    correctAnswerRule = `
- For ${bloom.question_type} questions:

  - options MUST be null

  - correct_answer MUST NOT be:
      "A", "B", "C", or "D"

  - correct_answer should contain:
      - actual output
      - expected code
      - debugging fix
      - or null

  - evaluation_criteria must explain how the answer will be evaluated`;
  }

  promptText = `You are an expert adaptive Java tutor using Bloom's Taxonomy.

Generate EXACTLY ONE adaptive Java assessment question.

STRICT RULES:
- difficulty MUST be exactly "${nextDiff}"
- blooms_level MUST be exactly "${bloom.name}"
- question_type MUST be exactly "${bloom.question_type}"
- Return ONLY valid JSON
- No markdown
- No explanations outside JSON
- Ensure JSON is COMPLETE and properly closed

IMPORTANT MCQ RULES:
- For MCQ questions:
  - options MUST be:
    {
      "A":"...",
      "B":"...",
      "C":"...",
      "D":"..."
    }

  - correct_answer MUST contain ONLY:
      "A", "B", "C", or "D"

  - NEVER place:
      - explanations
      - reasoning
      - full sentences
      - option text
      inside correct_answer

VALID:
"correct_answer":"A"

INVALID:
"correct_answer":"Because synchronization prevents race conditions"

IMPORTANT NON-MCQ RULES:
- For NON-MCQ questions:
  - options MUST be null

  - correct_answer MUST NOT be:
      "A", "B", "C", or "D"

  - correct_answer should contain:
      - actual output
      - expected code
      - debugging fix
      - or null

VALID:
"correct_answer":"31"

VALID:
"correct_answer":"public int sum(int a,int b)"

INVALID:
"correct_answer":"B"

${correctAnswerRule}

LEARNER STATE:
- Topic: ${topic}
- Mastery: ${masteryScore}%
- Questions Asked: ${questionsAsked}
- Consecutive Correct: ${consecutiveCorrect}
- Consecutive Wrong: ${consecutiveWrong}
${misconceptionNote}
${errorNote}
${conceptFocusSection}

ADAPTIVE INSTRUCTION:
${adaptiveInstruction}

${avoidSection}

QUESTION INSTRUCTION:
${bloom.instruction}

Required JSON structure:
{
  "question_id":"Q_DYNAMIC",
  "topic":"${topic}",
  "difficulty":"${nextDiff}",
  "blooms_level":"${bloom.name}",
  "question_type":"${bloom.question_type}",
  "question_text":"Actual adaptive question",
  "code_snippet":"Java code if required, otherwise null",

  "options": ${
    bloom.question_type === 'mcq'
      ? '{"A":"...","B":"...","C":"...","D":"..."}'
      : 'null'
  },

  "correct_answer": ${
    bloom.question_type === 'mcq'
      ? '"A"'
      : '"actual expected output or null"'
  },

  "evaluation_criteria":"Specific evaluation criteria",
  "hints":[
    "Hint targeting the weak concept",
    "More specific hint"
  ]
}`;
}

// ── Stable Ollama Payload ────────────────────────────────────
const ollamaPayload = {
  model: "gemma4:latest",
  prompt: promptText,
  stream: false,
  format: "json",
  options: {
    temperature: 0.1,
    num_predict: 1100,
    num_ctx: 4096,
    keep_alive: '10m'
  }
};

return [{
  json: {
    ...data,
    next_question_prompt: promptText,
    ollama_payload: ollamaPayload,
    feedback_report: null,
    is_remediation: isRemediationMode,
    is_partial_correct: isPartialCorrect,
    weak_concepts: weakConcepts
  }
}];

const data    = $input.first().json;
const session = data.updated_session;

const topicResults = Object.entries(session.topic_scores || {}).map(([topic, scores]) => ({
  topic,
  mastery_score:   scores.mastery_score,
  questions_asked: scores.questions_asked,
  correct:         scores.correct,
  accuracy:        scores.questions_asked > 0 ? Math.round((scores.correct / scores.questions_asked) * 100) : 0,
  is_mastered:     scores.is_mastered
}));

const overallAccuracy = session.total_questions_asked > 0
  ? Math.round((session.correct_answers / session.total_questions_asked) * 100) : 0;

// Build full Q&A review from session history for learner reference
// Each entry has question, learner answer, correct answer, result, feedback
const history = session.session_history || [];
const fullQaReview = history.map((h, idx) => ({
  question_number:  idx + 1,
  topic:            h.topic || session.selected_topic,
  question_id:      h.question_id,
  question_text:    h.question_text,
  question_type:    h.question_type,
  difficulty:       h.difficulty,
  learner_answer:   h.submitted_answer,
  correct_answer:   h.correct_answer,
  is_correct:       h.is_correct,
  mastery_after:    h.score,
  timestamp:        h.timestamp
}));

return [{ json: {
  ...data,
  next_question: null,
  full_qa_review: fullQaReview,
  session_summary: {
    session_id:               session.session_id,
    total_questions:          session.total_questions_asked,
    correct_answers:          session.correct_answers,
    overall_accuracy:         overallAccuracy,
    topics_covered:           topicResults,
    mastered_topics:          topicResults.filter(t => t.is_mastered).map(t => t.topic),
    session_duration_minutes: Math.round((new Date() - new Date(session.session_started_at)) / 60000),
    overall_mastery:          Math.round(topicResults.reduce((sum, t) => sum + t.mastery_score, 0) / Math.max(topicResults.length, 1))
  }
}}];

// ============================================================
// PARSE NEXT QUESTION
