// ============================================================


// ============================================================
// 1. GET CURRENT INPUT
// ============================================================

const input = $input.first().json || {};

console.log('====================================================');
console.log('PARSE NEXT QUESTION STARTED');
console.log('Input keys:', Object.keys(input));
console.log('====================================================');


// ============================================================
// 2. RECOVER SESSION DATA FROM CURRENT INPUT ONLY
// ============================================================
//
// Priority:
//
// ame_context.session
// updated_session
// session
// session_state
// direct fields
//
// No $() node references are used.
// ============================================================

const contextSession =
  input.ame_context?.session ||
  {};

const updatedSession =
  input.updated_session ||
  input.session ||
  input.session_state ||
  {};


// Merge the two possible session objects.
//
// ame_context.session is allowed to override older
// session values because it is the normalized context.

const sess = {
  ...updatedSession,
  ...contextSession
};


// ============================================================
// 3. NORMALIZE SESSION VALUES
// ============================================================

const sessionId =
  sess.session_id ||
  input.session_id ||
  input.ame_context?.session_id ||
  '';

const learnerId =
  sess.learner_id ||
  input.learner_id ||
  input.ame_context?.learner_id ||
  '';

const selectedTopic =
  sess.selected_topic ||
  sess.current_topic ||
  sess.topic ||
  input.selected_topic ||
  input.current_topic ||
  input.topic ||
  '';

const currentDifficulty =
  sess.current_difficulty ||
  sess.difficulty ||
  input.current_difficulty ||
  input.difficulty ||
  'easy';

const bloomLevel =
  sess.bloom_level ||
  sess.blooms_level ||
  input.bloom_level ||
  input.blooms_level ||
  '';


// ============================================================
// 4. SESSION VALIDATION
// ============================================================
//
// Do not immediately fail if session_id is absent because
// some branches may construct it later.
//
// But we do need at least some session context to safely
// generate an adaptive question.
// ============================================================

if (
  !sessionId &&
  !learnerId &&
  !selectedTopic
) {

  console.log(
    'WARNING: No session_id, learner_id, or topic found.'
  );

  console.log(
    'Incoming data:',
    JSON.stringify(input, null, 2)
  );
}


// ============================================================
// 5. GET OLLAMA RESPONSE
// ============================================================

let rawText = '';


// Standard Ollama response
if (
  typeof input.response === 'string'
) {

  rawText = input.response;

}


// Alternative response field
else if (
  typeof input.output === 'string'
) {

  rawText = input.output;

}


// Generic text field
else if (
  typeof input.text === 'string'
) {

  rawText = input.text;

}


// Generic content field
else if (
  typeof input.content === 'string'
) {

  rawText = input.content;

}


// Chat-style response
else if (
  typeof input.message?.content === 'string'
) {

  rawText = input.message.content;

}


// Nested response
else if (
  typeof input.data?.response === 'string'
) {

  rawText = input.data.response;

}


if (!rawText) {

  throw new Error(
    'No Ollama response found. Expected response, output, text, content, message.content, or data.response.'
  );
}


console.log('====================================================');
console.log('RAW OLLAMA RESPONSE');
console.log(rawText);
console.log('====================================================');


// ============================================================
// 6. CLEAN MARKDOWN
// ============================================================

rawText = String(rawText)
  .replace(/```json/gi, '')
  .replace(/```javascript/gi, '')
  .replace(/```js/gi, '')
  .replace(/```/g, '')
  .trim();


// ============================================================
// 7. EXTRACT JSON OBJECT SAFELY
// ============================================================
//
// We do NOT simply use lastIndexOf('}') because Java code
// or strings may contain braces.
//
// This function finds the actual matching closing brace.
// ============================================================

function extractJsonObject(text) {

  const firstBrace =
    text.indexOf('{');

  if (firstBrace === -1) {

    throw new Error(
      'Ollama response does not contain a JSON object.'
    );
  }


  let depth = 0;
  let insideString = false;
  let escaped = false;


  for (
    let i = firstBrace;
    i < text.length;
    i++
  ) {

    const char = text[i];


    // Handle escaped characters
    if (escaped) {

      escaped = false;

      continue;
    }


    if (char === '\\') {

      escaped = true;

      continue;
    }


    // Toggle JSON string state
    if (char === '"') {

      insideString =
        !insideString;

      continue;
    }


    // Ignore braces inside strings
    if (insideString) {

      continue;
    }


    if (char === '{') {

      depth++;
    }


    if (char === '}') {

      depth--;

      if (depth === 0) {

        return text.substring(
          firstBrace,
          i + 1
        );
      }
    }
  }


  throw new Error(
    'Ollama returned incomplete/truncated JSON.'
  );
}


// ============================================================
// 8. PARSE QUESTION JSON
// ============================================================

let nextQuestion;

try {

  const cleanedJson =
    extractJsonObject(rawText);


  console.log('====================================================');
  console.log('CLEANED QUESTION JSON');
  console.log(cleanedJson);
  console.log('====================================================');


  nextQuestion =
    JSON.parse(cleanedJson);


} catch (error) {

  console.log(
    'JSON PARSE ERROR:',
    error.message
  );


  console.log(
    'LAST 2000 CHARACTERS:',
    rawText.substring(
      Math.max(
        0,
        rawText.length - 2000
      )
    )
  );


  throw new Error(
    `Failed to parse Ollama question JSON: ${error.message}`
  );
}


// ============================================================
// 9. NORMALIZE ALTERNATIVE FIELD NAMES
// ============================================================


// question -> question_text
if (
  nextQuestion.question &&
  !nextQuestion.question_text
) {

  nextQuestion.question_text =
    nextQuestion.question;
}


// answer -> correct_answer
if (
  nextQuestion.answer &&
  !nextQuestion.correct_answer
) {

  nextQuestion.correct_answer =
    nextQuestion.answer;
}


// explanation -> evaluation_criteria
if (
  nextQuestion.explanation &&
  !nextQuestion.evaluation_criteria
) {

  nextQuestion.evaluation_criteria =
    nextQuestion.explanation;
}


// options automatically indicate MCQ
if (
  nextQuestion.options &&
  !nextQuestion.question_type
) {

  nextQuestion.question_type =
    'mcq';
}


// ============================================================
// 10. FILL TOPIC FROM SESSION
// ============================================================

if (
  !nextQuestion.topic
) {

  nextQuestion.topic =
    selectedTopic;
}


// ============================================================
// 11. FILL DIFFICULTY FROM SESSION
// ============================================================

if (
  !nextQuestion.difficulty
) {

  nextQuestion.difficulty =
    currentDifficulty;
}


// ============================================================
// 12. FILL BLOOM LEVEL
// ============================================================

if (
  !nextQuestion.blooms_level
) {

  nextQuestion.blooms_level =
    bloomLevel;
}


// ============================================================
// 13. NORMALIZE QUESTION TYPE
// ============================================================

nextQuestion.question_type =
  String(
    nextQuestion.question_type ||
    'mcq'
  )
    .trim()
    .toLowerCase();


// ============================================================
// 14. ALWAYS GENERATE A SERVER-SIDE QUESTION ID
// ============================================================
// The LLM is never allowed to own the persistent question ID.
// The prompt may contain PLACEHOLDER/Q_DYNAMIC, but this node
// ALWAYS replaces it with a unique ID before MongoDB save and
// before the question is returned to the frontend.

const generatedQuestionId =
  'Q_' +
  Date.now() +
  '_' +
  Math.random()
    .toString(36)
    .substring(2, 8);

nextQuestion.question_id = generatedQuestionId;

// Hard safety guard: a placeholder must never leave this node.
const forbiddenQuestionIds = new Set([
  'Q_DYNAMIC',
  'PLACEHOLDER',
  'QUESTION_ID',
  'TEMP',
  'TEMP_ID',
  'undefined',
  'null'
]);

if (forbiddenQuestionIds.has(String(nextQuestion.question_id).trim().toUpperCase())) {
  throw new Error(
    'CRITICAL: Invalid question_id reached Parse Next Question output.'
  );
}

console.log('SERVER-GENERATED QUESTION ID:', nextQuestion.question_id);


// ── Flag whether this question needs the code sandbox (frontend hint) ──
nextQuestion.requires_sandbox =
  nextQuestion.question_type === 'code_completion' ||
  nextQuestion.question_type === 'coding_challenge';


// ============================================================
// 15. REQUIRED FIELD VALIDATION
// ============================================================

const requiredFields = [
  'question_id',
  'question_text',
  'question_type',
  'topic',
  'difficulty'
];


for (
  const field of requiredFields
) {

  if (
    nextQuestion[field] === undefined ||
    nextQuestion[field] === null ||
    String(nextQuestion[field]).trim() === ''
  ) {

    throw new Error(
      `Missing required field: ${field}`
    );
  }
}


// ============================================================
// 16. MCQ VALIDATION
// ============================================================

if (
  nextQuestion.question_type === 'mcq'
) {


  // ----------------------------------------------------------
  // Options must exist
  // ----------------------------------------------------------

  if (
    !nextQuestion.options
  ) {

    throw new Error(
      'MCQ question missing options.'
    );
  }


  // ----------------------------------------------------------
  // Convert array to A/B/C/D
  // ----------------------------------------------------------

  if (
    Array.isArray(
      nextQuestion.options
    )
  ) {

    if (
      nextQuestion.options.length !== 4
    ) {

      throw new Error(
        `MCQ must contain exactly 4 options. Received ${nextQuestion.options.length}.`
      );
    }


    nextQuestion.options = {

      A: String(
        nextQuestion.options[0]
      ),

      B: String(
        nextQuestion.options[1]
      ),

      C: String(
        nextQuestion.options[2]
      ),

      D: String(
        nextQuestion.options[3]
      )
    };
  }


  // ----------------------------------------------------------
  // Validate A/B/C/D
  // ----------------------------------------------------------

  const requiredOptions = [
    'A',
    'B',
    'C',
    'D'
  ];


  for (
    const option of requiredOptions
  ) {

    if (
      nextQuestion.options[option] === undefined ||
      nextQuestion.options[option] === null ||
      String(
        nextQuestion.options[option]
      ).trim() === ''
    ) {

      throw new Error(
        `MCQ is missing option ${option}.`
      );
    }
  }


  // ----------------------------------------------------------
  // correct_answer MUST exist
  //
  // IMPORTANT:
  // We do NOT default to A.
  // ----------------------------------------------------------

  if (
    nextQuestion.correct_answer === undefined ||
    nextQuestion.correct_answer === null ||
    String(
      nextQuestion.correct_answer
    ).trim() === ''
  ) {

    throw new Error(
      'MCQ question is missing correct_answer. Refusing to guess the answer.'
    );
  }


  // ----------------------------------------------------------
  // Normalize correct answer
  // ----------------------------------------------------------

  let answer =
    String(
      nextQuestion.correct_answer
    ).trim();


  // Examples:
  //
  // A
  // a
  // A.
  // A)
  // A: answer
  //

  const letterMatch =
    answer.match(
      /^([ABCD])(?:[\.\):\s]|$)/i
    );


  if (
    letterMatch
  ) {

    nextQuestion.correct_answer =
      letterMatch[1]
        .toUpperCase();

  } else {

    // --------------------------------------------------------
    // Try matching full answer text to an option.
    // --------------------------------------------------------

    const answerLower =
      answer.toLowerCase();

    let matched =
      false;


    for (
      const option of requiredOptions
    ) {

      const optionText =
        String(
          nextQuestion.options[option]
        )
          .trim()
          .toLowerCase();


      if (
        answerLower === optionText ||
        answerLower.includes(optionText) ||
        optionText.includes(answerLower)
      ) {

        nextQuestion.correct_answer =
          option;

        matched =
          true;

        break;
      }
    }


    if (
      !matched
    ) {

      throw new Error(
        `Could not map correct_answer "${answer}" to A/B/C/D.`
      );
    }
  }


  // ----------------------------------------------------------
  // Final validation
  // ----------------------------------------------------------

  nextQuestion.correct_answer =
    String(
      nextQuestion.correct_answer
    )
      .trim()
      .toUpperCase();


  if (
    ![
      'A',
      'B',
      'C',
      'D'
    ].includes(
      nextQuestion.correct_answer
    )
  ) {

    throw new Error(
      `Invalid MCQ correct_answer: ${nextQuestion.correct_answer}`
    );
  }

}


// ============================================================
// 17. NON-MCQ VALIDATION
// ============================================================

else {

  nextQuestion.options =
    null;


  const codeQuestionTypes = [
    'code_completion',
    'code_tracing',
    'debugging',
    'coding_challenge'
  ];


  if (
    codeQuestionTypes.includes(
      nextQuestion.question_type
    )
  ) {

    if (
      !nextQuestion.code_snippet ||
      String(
        nextQuestion.code_snippet
      ).trim() === ''
    ) {

      // PATCH: Do not crash the whole workflow when the LLM omits
      // code_snippet for a code-type question. Log a warning and
      // fall back to a minimal placeholder snippet so the session
      // can continue; the question_text still carries the task.
      console.log(
        `WARNING: ${nextQuestion.question_type} question missing code_snippet. Using fallback placeholder.`
      );

      nextQuestion.code_snippet =
        '// No code snippet was provided for this question.\\n' +
        '// Please refer to the question text above.';
    }
  }


  // Non-MCQ questions should not have A/B/C/D
  // as their correct answer.

  if (
    [
      'A',
      'B',
      'C',
      'D'
    ].includes(
      String(
        nextQuestion.correct_answer || ''
      )
        .trim()
        .toUpperCase()
    )
  ) {

    nextQuestion.correct_answer =
      null;
  }
}


// ============================================================
// 18. LIMIT FIELD SIZES
// ============================================================

if (
  typeof nextQuestion.question_text === 'string' &&
  nextQuestion.question_text.length > 2500
) {

  nextQuestion.question_text =
    nextQuestion.question_text.substring(
      0,
      2500
    );
}


if (
  typeof nextQuestion.code_snippet === 'string' &&
  nextQuestion.code_snippet.length > 3000
) {

  nextQuestion.code_snippet =
    nextQuestion.code_snippet.substring(
      0,
      3000
    );
}


if (
  typeof nextQuestion.evaluation_criteria === 'string' &&
  nextQuestion.evaluation_criteria.length > 1200
) {

  nextQuestion.evaluation_criteria =
    nextQuestion.evaluation_criteria.substring(
      0,
      1200
    );
}


if (
  Array.isArray(
    nextQuestion.hints
  )
) {

  nextQuestion.hints =
    nextQuestion.hints
      .slice(0, 2)
      .map(
        hint =>
          String(hint)
            .substring(0, 200)
      );
}


// ============================================================
// 19. BUILD FINAL SESSION
// ============================================================
//
// Preserve all existing session fields.
// Do NOT replace the entire session with a small object.
// ============================================================

const finalSession = {
  ...updatedSession,
  ...contextSession
};


// ============================================================
// 19.5 AUTHORITATIVE REQUEST IDS
// ============================================================
// For answer-submission flows, the original webhook request is the
// authoritative source for session_id and learner_id. Resolve these
