  if (diffCounts.easy.correct === diffCounts.easy.asked && diffCounts.easy.asked > 0)
    strengths.push(`Demonstrated solid foundational recall across ${diffCounts.easy.asked} easy-level questions`);
  if (strengths.length === 0)
    strengths.push(`Completed ${totalQ} questions with ${overallAccuracy}% accuracy at ${bloomLevel}`);

  // ── Key weaknesses — only when errors exist ────────────────
  const weaknesses = [];
  if (overallAccuracy < 80) {
    const incorrectTopics = Object.entries(topicScores)
      .filter(([,s]) => s.correct < s.questions_asked)
      .map(([topic]) => topic);
    if (incorrectTopics.length > 0)
      weaknesses.push(`Incorrect answers observed in: ${incorrectTopics.join(', ')} — review the specific sub-concepts involved`);
  }
  // If accuracy >= 95, weaknesses stays []

  // ── Per-topic reports ─────────────────────────────────────
  const topicReports = Object.entries(topicScores).map(([topic, s]) => {
    const gap      = profileGaps.find(g => g.topic === topic) || {};
    const mastery  = s.mastery_score   || 0;
    const asked    = s.questions_asked || 0;
    const correct  = s.correct         || 0;
    const accuracy = asked > 0 ? Math.round((correct/asked)*100) : 0;
    const mastered = s.is_mastered || false;

    const topicHistory  = history.filter(h => (h.topic || session.selected_topic) === topic);
    const hardCorrect   = topicHistory.filter(h => h.difficulty === 'hard' && h.is_correct);
    const codingCorrect = topicHistory.filter(h => h.question_type !== 'mcq' && h.is_correct);
    const hasErrors     = correct < asked;

    // Strength: cite actual question types and difficulty levels solved
    let strength = '';
    if (hardCorrect.length > 0 && codingCorrect.length > 0)
      strength = `Solved ${hardCorrect.length} hard-difficulty ${[...new Set(hardCorrect.map(h=>h.question_type))].join('/')} task(s) correctly on ${topic}, demonstrating deep implementation ability at ${bloomLevel}`;
    else if (codingCorrect.length > 0)
      strength = `Correctly completed ${codingCorrect.length} code-based question(s) on ${topic}, applying concepts in practice`;
    else if (correct === asked && asked > 0)
      strength = `Answered all ${asked} questions correctly on ${topic} with ${accuracy}% accuracy`;
    else
      strength = `Demonstrated partial understanding of ${topic} across ${correct}/${asked} correct answers`;

    // Weakness: only when errors exist, cite specific gap data
    let weakness = 'none observed';
    if (hasErrors) {
      const knownMisconceptions = gap.misconceptions || [];
      const knownErrors         = gap.error_patterns || [];
      const details = [...knownMisconceptions.slice(0,1), ...knownErrors.slice(0,1)].join('; ');
      weakness = details.length > 0
        ? `Struggled with: ${details}`
        : `${asked - correct} question(s) answered incorrectly on ${topic} — focus on the sub-concepts from those specific questions`;
    }

    // Misconceptions: only from KAA profile, only when errors exist
    const misconceptions = hasErrors ? (gap.misconceptions || []).slice(0,2) : [];

    // Improvement plan: advanced if mastered, targeted if not
    let improvement = '';
    if (mastered && mastery >= 90)
      improvement = `Mastered at ${mastery}%. Progress to advanced ${topic} topics such as ${topic.includes('OOP') ? 'design patterns and SOLID principles' : topic.includes('Thread') ? 'concurrent data structures and Fork/Join framework' : topic.includes('Collection') ? 'stream processing and functional-style collection operations' : 'algorithmic optimization and real-world application development'}`;
    else if (mastered)
      improvement = `Topic mastered at ${mastery}%. Consolidate by implementing a project that integrates ${topic} with other Java concepts`;
    else
      improvement = `Focus on the ${asked - correct} incorrect question(s) — specifically the sub-concepts: ${(gap.error_patterns || ['core concepts']).slice(0,2).join(', ')}`;

    // Recommended next topics
    const nextTopics = mastered
      ? [ topic.includes('OOP') ? 'Design Patterns (GoF)' : topic.includes('Thread') ? 'Java Concurrent Collections' : topic.includes('Collection') ? 'Java Streams and Functional Interfaces' : `Advanced ${topic}` ]
      : [ topic ];

    return {
      topic_name:          topic,
      mastery_percentage:  mastery,
      is_mastered:         mastered,
      questions_asked:     asked,
      correct_answers:     correct,
      accuracy:            accuracy,
      performance_level:   mastery >= 90 ? 'excellent' : mastery >= 75 ? 'good' : mastery >= 60 ? 'satisfactory' : 'needs_improvement',
      strengths:           strength,
      weaknesses:          weakness,
      misconceptions_found: misconceptions,
      improvement_plan:    improvement,
      advanced_readiness:  mastered && mastery >= 85 ? 'Ready for advanced topics' : 'Continue building mastery',
      recommended_next_topics: nextTopics
    };
  });

  // ── Learning path ─────────────────────────────────────────
  const masteredTopics   = topicReports.filter(t => t.is_mastered).map(t => t.topic_name);
  const unmasteredTopics = topicReports.filter(t => !t.is_mastered).map(t => t.topic_name);

  const immediateFocus = unmasteredTopics.length > 0
    ? `Deepen mastery in ${unmasteredTopics[0]} — focus on the specific sub-concepts from the incorrect answers in this session`
    : `Progress to advanced Java topics building on your demonstrated mastery of: ${masteredTopics.join(', ')}`;

  const nextStage = masteredTopics.length > 0 && unmasteredTopics.length === 0
    ? [`Tackle advanced-difficulty ${masteredTopics[0]} implementation projects`, 'Explore Java design patterns and architectural concepts']
    : [`Complete ${unmasteredTopics[0] || 'remaining topics'} to mastery level`, 'Revisit the specific question types where errors occurred'];

  const advancedReady = masteredTopics.map(t =>
    t.includes('OOP') ? 'Design Patterns' : t.includes('Thread') ? 'Concurrent Collections' : t.includes('Collection') ? 'Java Streams API' : `Advanced ${t}`
  );

  // ── Overall assessment ────────────────────────────────────
  let assessment = '';
  if (overallMastery >= 90 && solvedHardCoding)
    assessment = `Demonstrated exceptional performance with ${overallAccuracy}% accuracy and ${overallMastery}% mastery. Successfully reached ${bloomLevel} by solving hard-difficulty ${hardTypes.join(' and ')} tasks, showing strong algorithmic thinking and implementation ability.`;
  else if (overallMastery >= 75)
    assessment = `Performed strongly across the session with ${overallAccuracy}% accuracy and ${overallMastery}% overall mastery. Reached ${bloomLevel} on the Bloom's Taxonomy scale.`;
  else
    assessment = `Completed the assessment with ${overallAccuracy}% accuracy and ${overallMastery}% overall mastery. The session progressed through ${bloomLevel} on the Bloom's Taxonomy scale.`;

  // ── Motivational message — evidence-based ─────────────────
  let motivation = '';
  if (overallMastery >= 90 && solvedHardCoding)
    motivation = `Outstanding performance — ${overallAccuracy}% accuracy and mastery of ${bloomLevel} demonstrates genuine Java expertise. Your ability to solve hard ${hardTypes.join(' and ')} challenges shows you are ready for professional-level Java development.`;
  else if (overallMastery >= 75)
    motivation = `Strong session performance with ${overallMastery}% mastery. Your progression to ${bloomLevel} confirms solid Java understanding — keep advancing to the next challenge level.`;
  else
    motivation = `Good effort across ${totalQ} questions. Your ${overallMastery}% mastery shows a developing understanding of Java — focus on the specific sub-concepts from this session and your next assessment will show clear improvement.`;

  reportData = {
    report_title:                'Java Programming Assessment - Personalised Feedback Report',
    generated_at:                new Date().toISOString(),
    learner_id:                  session.learner_id,
    session_id:                  session.session_id,
    overall_assessment:          assessment,
    overall_grade:               grade,
    overall_mastery_percentage:  overallMastery,
    overall_accuracy_percentage: overallAccuracy,
    session_duration_minutes:    summary.session_duration_minutes,
    total_questions:             totalQ,
    total_correct:               totalCorrect,
    key_strengths:               strengths,
    key_weaknesses:              weaknesses,
    topic_reports:               topicReports,
    mastered_topics:             masteredTopics,
    topics_needing_improvement:  unmasteredTopics,
    misconceptions_to_address:   topicReports.flatMap(t => t.misconceptions_found),
    learning_path: {
      immediate_focus:              immediateFocus,
      next_stage_recommendations:   nextStage,
      advanced_topics_ready_for:    advancedReady,
      week_1_goals:   [ nextStage[0] ],
      long_term_goals: advancedReady.length > 0 ? advancedReady : [ 'Build a complete Java project integrating all assessed topics' ]
    },
    recommended_resources: [
      { topic: 'Java General', resource_name: 'Official Java Documentation', resource_type: 'website', url_hint: 'docs.oracle.com/javase' },
      { topic: 'Java General', resource_name: 'Effective Java — Joshua Bloch', resource_type: 'book', url_hint: 'effectivejava.com' }
    ],
    final_instructor_summary: assessment,
    next_assessment_recommendation: masteredTopics.length === topicReports.length
      ? `All topics mastered. Progress to advanced Java concepts — recommended: ${advancedReady.join(', ')}`
      : `Reassess ${unmasteredTopics.join(', ')} after targeted practice on the specific sub-concepts identified in this session.`,
    motivational_message: motivation
  };
}

return [{ json: { ...prevData, feedback_report: reportData } }];

