  }
}];

// ============================================================
// Build Rubric Evaluation Prompt
// Question-type-aware rubric — MCQ vs Open-ended
// MCQ: correctness ONLY — no reasoning, no explanation quality
// Open-ended: full multi-dimensional rubric
// ============================================================
const data            = $input.first().json;
const question        = data.question;
const evalResult      = data.evaluation_result;
const submittedAnswer = data.submittedAnswer;
const qType           = question.question_type || 'mcq';
const difficulty      = question.difficulty    || 'easy';
const topic           = question.topic         || 'Java';

// ── Question type classification ────────────────────────────
// MCQ: binary choice — only correctness matters
// Open-ended: multi-dimensional quality evaluation
const isMcq = (qType === 'mcq');

// ── Sandbox execution result (code_completion / coding_challenge only) ──
const sandbox = data.sandbox_result || null;
const sandboxNote = (sandbox && sandbox.attempted && sandbox.status !== 'sandbox_unavailable' &&
  (qType === 'code_completion' || qType === 'coding_challenge'))
  ? `\nSANDBOX EXECUTION RESULT (actual compiler/runtime output — weight this heavily for the "correctness" criterion):\nCompiled: ${sandbox.compiled}\nStatus: ${sandbox.status}\n${sandbox.compile_output ? `Compile Errors:\n${sandbox.compile_output}\n` : ''}${sandbox.stdout ? `Program Output (stdout):\n${sandbox.stdout}\n` : ''}${sandbox.stderr ? `Runtime Errors (stderr):\n${sandbox.stderr}\n` : ''}\n`
  : '';

// ── Define rubric criteria by question type ─────────────────
// MCQ: ONLY correctness — single criterion, weight 1.0
// Gemma4 must NOT be asked to evaluate reasoning for MCQ
const rubricsByType = {
  mcq: [
    {
      criterion:   'correctness',
      weight:      1.00,
      description: 'Whether the learner selected the correct answer option. ' +
                   'IMPORTANT: This is a multiple choice question. ' +
                   'Do NOT evaluate reasoning, explanation quality, or conceptual depth. ' +
                   'Score 100 if correct option selected, 0 if wrong option selected.'
    }
  ],
  conceptual: [
    { criterion: 'correctness',              weight: 0.30, description: 'Factual accuracy of the response'                                  },
    { criterion: 'conceptual_understanding', weight: 0.35, description: 'Depth of understanding demonstrated in the explanation'            },
    { criterion: 'logical_reasoning',        weight: 0.25, description: 'Coherence and logical flow of the explanation'                     },
    { criterion: 'authenticity',             weight: 0.10, description: 'Human-like reasoning vs. mechanical/copy-paste response'           }
  ],
  code_completion: [
    { criterion: 'correctness',              weight: 0.35, description: 'Code produces the correct output'                                  },
    { criterion: 'conceptual_understanding', weight: 0.25, description: 'Correct use of Java constructs and concepts'                      },
    { criterion: 'code_quality',             weight: 0.20, description: 'Code readability, naming, and structure'                          },
    { criterion: 'logical_reasoning',        weight: 0.15, description: 'Logical approach used to solve the problem'                       },
    { criterion: 'authenticity',             weight: 0.05, description: 'Genuine learner reasoning vs. template-copied code'               }
  ],
  code_tracing: [
    { criterion: 'correctness',              weight: 0.50, description: 'Correct final output or traced value'                             },
    { criterion: 'logical_reasoning',        weight: 0.35, description: 'Evidence of step-by-step trace reasoning'                        },
    { criterion: 'conceptual_understanding', weight: 0.15, description: 'Shows understanding of what the code does'                       }
  ],
  debugging: [
    { criterion: 'correctness',              weight: 0.30, description: 'All bugs correctly identified and fixed'                         },
    { criterion: 'logical_reasoning',        weight: 0.30, description: 'Systematic debugging approach shown'                             },
    { criterion: 'code_quality',             weight: 0.20, description: 'Fixed code follows good practices'                               },
    { criterion: 'conceptual_understanding', weight: 0.15, description: 'Understands WHY the bugs exist'                                  },
    { criterion: 'authenticity',             weight: 0.05, description: 'Personal debugging process visible'                              }
  ],
  coding_challenge: [
    { criterion: 'correctness',              weight: 0.30, description: 'Solution produces correct output for all cases'                  },
    { criterion: 'logical_reasoning',        weight: 0.25, description: 'Algorithm design and problem-solving approach'                   },
    { criterion: 'code_quality',             weight: 0.20, description: 'Code readability, structure, naming conventions'                 },
    { criterion: 'solution_efficiency',      weight: 0.15, description: 'Time/space complexity and optimal approach'                      },
    { criterion: 'conceptual_understanding', weight: 0.07, description: 'Correct use of Java-specific features'                           },
    { criterion: 'authenticity',             weight: 0.03, description: 'Genuine problem-solving vs. AI-generated pattern'                }
  ],
  descriptive: [
    { criterion: 'correctness',              weight: 0.30, description: 'Factual accuracy of the response'                                },
    { criterion: 'conceptual_understanding', weight: 0.35, description: 'Depth of conceptual understanding demonstrated'                  },
    { criterion: 'logical_reasoning',        weight: 0.25, description: 'Coherence and logical flow of explanation'                       },
    { criterion: 'authenticity',             weight: 0.10, description: 'Human-like reasoning vs. copied response'                        }
  ]
};

// Fallback to coding_challenge for unknown open-ended types
const criteria = rubricsByType[qType] || (isMcq ? rubricsByType['mcq'] : rubricsByType['coding_challenge']);

// Build criteria list for the prompt
const criteriaList = criteria.map(c =>
  `  - ${c.criterion} (weight: ${Math.round(c.weight * 100)}%): ${c.description}`
).join('\n');

const criteriaJson = criteria.map(c =>
  `    {"criterion": "${c.criterion}", "score": <0-100>, "weight": ${c.weight}, "evidence": "<specific evidence from the answer>", "feedback": "<1 sentence specific feedback for this criterion>"}`
).join(',\n');

// ── MCQ-specific prompt (correctness only, no reasoning eval) ──
let promptText;

if (isMcq) {
  const correct   = String(question.correct_answer || '').trim().toUpperCase();
  const submitted = String(submittedAnswer || '').trim().toUpperCase();
  const isCorrect = evalResult.is_correct;
  const score     = isCorrect ? 100 : 0;

  promptText = `You are a Java assessment rubric evaluator.
This is a MULTIPLE CHOICE question. The learner selected a single option letter.

QUESTION CONTEXT:
Topic: ${topic}
Difficulty: ${difficulty.toUpperCase()}
Question Type: MCQ (Multiple Choice)
Question: ${String(question.question_text || '').substring(0, 300)}
Correct Option: ${correct}
Learner Selected: ${submitted}
Result: ${isCorrect ? 'CORRECT' : 'INCORRECT'}

CRITICAL INSTRUCTION:
This is MCQ. You MUST evaluate ONLY whether the correct option was selected.
Do NOT evaluate:
- Reasoning quality
- Explanation depth
- Conceptual articulation
- How well the learner explains their choice
The learner only had to select A, B, C, or D. That is the complete task.

RUBRIC: Single criterion — correctness only.
Correctness score: ${score} (${isCorrect ? '100 because correct option was selected' : '0 because wrong option was selected'})

Respond with ONLY valid JSON:
{
  "rubric_criteria": [
    {"criterion": "correctness", "score": ${score}, "weight": 1.0, "evidence": "${isCorrect ? 'Learner selected the correct option ' + correct : 'Learner selected ' + submitted + ' but correct was ' + correct}", "feedback": "${isCorrect ? 'Correct option selected.' : 'Incorrect option selected. The correct answer was ' + correct + '.'}"}
  ],
  "weighted_rubric_score": ${score},
  "performance_level": "${score === 100 ? 'Excellent' : 'Needs_Improvement'}",
  "strongest_area": "correctness",
  "weakest_area": "${score === 100 ? 'None' : 'correctness'}",
  "reasoning_quality": "N/A - MCQ does not require reasoning",
  "authenticity_flag": "N/A - MCQ",
  "rubric_summary": "${isCorrect ? 'Learner correctly identified option ' + correct + ' for this MCQ question.' : 'Learner selected ' + submitted + ' instead of the correct option ' + correct + '.'}",
  "strengths_observed": "${isCorrect ? 'Correct answer selected.' : 'Attempted the question.'}",
  "weaknesses_observed": "${isCorrect ? 'None' : 'Selected wrong option ' + submitted + '. Correct was ' + correct + '.'}",
  "concept_misunderstanding": ${isCorrect ? 'null' : '"May not fully understand the concept tested by this question."'},
  "improvement_roadmap": "${isCorrect ? 'Continue to the next question.' : 'Review the concept of ' + topic + ' and understand why option ' + correct + ' is correct.'}"
}`;

} else {
  // ── Open-ended prompt (full multi-dimensional rubric) ───────
  promptText = `You are an expert Java programming assessment rubric evaluator.
Evaluate the following learner response using a structured rubric.

QUESTION CONTEXT:
Topic: ${topic}
Difficulty: ${difficulty.toUpperCase()}
Question Type: ${qType}
Question: ${String(question.question_text || '').substring(0, 300)}
${question.code_snippet && question.code_snippet !== 'null' ? `Code Provided:\n${String(question.code_snippet).substring(0, 400)}` : ''}
Expected Answer: ${String(question.correct_answer || '').substring(0, 200)}
Evaluation Criteria: ${question.evaluation_criteria || ''}

LEARNER RESPONSE:
${String(submittedAnswer || '').substring(0, 500)}
${sandboxNote}
INITIAL EVALUATION (for context):
Result: ${evalResult.is_correct ? 'CORRECT' : 'INCORRECT'}
Initial Score: ${evalResult.correctness_score}/100
What was correct: ${String(evalResult.what_is_correct || '').substring(0, 150)}
What was wrong: ${String(evalResult.what_is_wrong || '').substring(0, 150)}

RUBRIC CRITERIA TO EVALUATE:
${criteriaList}

SCORING RULES:
- Score each criterion from 0 to 100
- 0-20: No evidence or completely wrong
- 21-40: Minimal attempt, significant errors
- 41-60: Partial understanding, notable gaps
- 61-80: Good understanding, minor issues
- 81-100: Strong understanding, near perfect

IMPORTANT: Respond with ONLY a valid JSON object. No markdown, no extra text. Just raw JSON:
{
  "rubric_criteria": [
${criteriaJson}
  ],
  "weighted_rubric_score": <calculated weighted average 0-100>,
  "performance_level": "<Excellent|Good|Satisfactory|Needs_Improvement|Poor>",
  "strongest_area": "<criterion name where learner performed best>",
  "weakest_area": "<criterion name where learner needs most improvement>",
  "reasoning_quality": "<Deep|Surface|Minimal|Absent>",
  "authenticity_flag": "<Genuine|Likely_AI_Assisted|Unclear>",
  "rubric_summary": "<2-3 sentence summary of overall rubric performance>",
  "strengths_observed": "<specific strengths seen in the response>",
  "weaknesses_observed": "<specific weaknesses or gaps observed>",
  "concept_misunderstanding": "<any specific misconception identified, or null>",
  "improvement_roadmap": "<concrete step-by-step improvement suggestion>"
}`;
}

const ollamaPayload = {
  model: 'gemma4:latest',
  format: 'json',
  prompt: promptText,
  stream: false,
  // MCQ: smaller context fine, open-ended needs more
  options: isMcq
    ? { temperature: 0.0, num_predict: 350,  num_ctx: 1536, keep_alive: '10m' }
    : { temperature: 0.2, num_predict: 800, num_ctx: 3072, keep_alive: '10m' }
};

return [{ json: {
  ...data,
  is_mcq_rubric:   isMcq,
  rubric_prompt:   promptText,
  rubric_criteria: criteria,
  ollama_payload:  ollamaPayload
}}];

// ============================================================
// Parse Rubric Result
// Parses Gemma4 rubric response, calculates weighted score.
// MCQ: correctness-only fallback (no reasoning penalties)
// Open-ended: full rubric fallback
// ============================================================
const buildData    = $('Build Rubric Evaluation Prompt').first().json;
const llmResponse  = $input.first().json;
const evalResult   = buildData.evaluation_result;
const question     = buildData.question;
const criteria     = buildData.rubric_criteria || [];
const qType        = question.question_type || 'mcq';
const isMcq        = (qType === 'mcq');

let rubricResult;

try {
  const rawText     = llmResponse.response || '';
  const cleanedText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  rubricResult      = JSON.parse(cleanedText);

  if (!rubricResult.rubric_criteria || !Array.isArray(rubricResult.rubric_criteria)) {
    throw new Error('Missing rubric_criteria array');
  }

  // Recalculate weighted score from criteria to ensure accuracy
  let calcWeightedScore = 0;
  let totalWeight       = 0;
  for (const c of rubricResult.rubric_criteria) {
    const weight = Number(c.weight) || 0;
    const score  = Math.min(100, Math.max(0, Number(c.score) || 0));
    calcWeightedScore += score * weight;
    totalWeight       += weight;
  }
  if (totalWeight > 0) {
    rubricResult.weighted_rubric_score = Math.round(calcWeightedScore / totalWeight);
  }

  // ── MCQ post-parse enforcement ────────────────────────────
  // Even if Gemma4 returns reasoning fields for MCQ, override them
  if (isMcq) {
    const mcqScore = evalResult.is_correct ? 100 : 0;
    // Force correctness-only score for MCQ
    rubricResult.weighted_rubric_score = mcqScore;
    rubricResult.reasoning_quality     = 'N/A - MCQ does not require reasoning';
    rubricResult.authenticity_flag     = 'N/A - MCQ';
    // Override any reasoning-based criteria scores Gemma4 may have added
    if (rubricResult.rubric_criteria) {
      rubricResult.rubric_criteria = rubricResult.rubric_criteria.map(c => {
        if (c.criterion !== 'correctness') return null; // strip non-correctness criteria
        return { ...c, score: mcqScore, weight: 1.0 };
      }).filter(Boolean);
      // Ensure correctness criterion exists
      if (rubricResult.rubric_criteria.length === 0) {
        rubricResult.rubric_criteria = [{
          criterion: 'correctness',
          score:     mcqScore,
          weight:    1.0,
          evidence:  evalResult.is_correct ? 'Correct option selected' : 'Incorrect option selected',
          feedback:  evalResult.is_correct ? 'Correct.' : `Wrong. Correct was ${question.correct_answer}.`
        }];
      }
    }
  }

} catch(e) {

  if (isMcq) {
    // ── MCQ fallback: correctness ONLY, zero reasoning ──────
    const mcqScore = evalResult.is_correct ? 100 : 0;
    rubricResult = {
      rubric_criteria: [{
        criterion: 'correctness',
        score:     mcqScore,
        weight:    1.0,
        evidence:  evalResult.is_correct
          ? `Learner selected the correct option.`
          : `Learner selected wrong option. Correct was ${question.correct_answer}.`,
        feedback:  evalResult.is_correct
          ? 'Correct answer selected.'
          : `Incorrect. The correct answer is ${question.correct_answer}.`
      }],
      weighted_rubric_score:    mcqScore,
      performance_level:        mcqScore === 100 ? 'Excellent' : 'Needs_Improvement',
      strongest_area:           'correctness',
      weakest_area:             mcqScore === 100 ? 'None' : 'correctness',
      reasoning_quality:        'N/A - MCQ does not require reasoning',
      authenticity_flag:        'N/A - MCQ',
      rubric_summary:           evalResult.is_correct
        ? `Learner correctly answered this MCQ question on ${question.topic}.`
        : `Learner selected the wrong option for this MCQ question on ${question.topic}.`,
      strengths_observed:       evalResult.is_correct ? 'Correct option selected.' : 'Attempted the question.',
      weaknesses_observed:      evalResult.is_correct ? 'None' : `Selected wrong option. Correct was ${question.correct_answer}.`,
      concept_misunderstanding: evalResult.is_correct ? null : `May need to review the concept: ${question.topic}`,
      improvement_roadmap:      evalResult.is_correct
        ? 'Continue to the next question.'
        : `Review ${question.topic} and understand why option ${question.correct_answer} is correct.`,
      _rubric_fallback: true
    };

  } else {
    // ── Open-ended fallback: full rubric from evaluation ────
    const baseScore = evalResult.is_correct ? 80 : 20;
    const fallbackCriteria = criteria.map(c => ({
      criterion: c.criterion,
      score:     evalResult.is_correct
        ? Math.min(100, baseScore + Math.round(c.weight * 20))
        : Math.max(0,   20         - Math.round(c.weight * 10)),
      weight:   c.weight,
      evidence: evalResult.is_correct
        ? `Based on correct answer: ${evalResult.what_is_correct || 'Answer was correct'}`
        : `Based on incorrect answer: ${evalResult.what_is_wrong || 'Answer was wrong'}`,
      feedback: evalResult.is_correct
        ? `Good performance on ${c.criterion}`
        : `Needs improvement in ${c.criterion}`
    }));

    let fallbackWeighted = 0;
    for (const c of fallbackCriteria) { fallbackWeighted += c.score * c.weight; }

    rubricResult = {
      rubric_criteria:          fallbackCriteria,
      weighted_rubric_score:    Math.round(fallbackWeighted),
      performance_level:        evalResult.is_correct ? 'Good' : 'Needs_Improvement',
      strongest_area:           evalResult.is_correct ? (criteria[0]?.criterion || 'correctness') : 'None identified',
      weakest_area:             evalResult.is_correct ? 'None identified' : (criteria[criteria.length-1]?.criterion || 'correctness'),
      reasoning_quality:        evalResult.is_correct ? 'Surface' : 'Minimal',
      authenticity_flag:        'Unclear',
      rubric_summary:           evalResult.is_correct
        ? `The learner answered correctly on this ${question.topic} question.`
        : `The learner answered incorrectly on this ${question.topic} question and needs further practice.`,
      strengths_observed:       evalResult.what_is_correct || 'Attempted the question',
      weaknesses_observed:      evalResult.what_is_wrong   || 'Answer did not match expected',
      concept_misunderstanding: null,
      improvement_roadmap:      `Review the core concepts of ${question.topic} and practice similar ${qType} questions at ${question.difficulty} difficulty.`,
      _rubric_fallback:         true
    };
  }
}

// Clamp weighted_rubric_score to 0-100
rubricResult.weighted_rubric_score = Math.min(100, Math.max(0, rubricResult.weighted_rubric_score || 0));

// Performance level from score if missing
if (!rubricResult.performance_level) {
  const s = rubricResult.weighted_rubric_score;
  rubricResult.performance_level =
    s >= 90 ? 'Excellent' :
    s >= 75 ? 'Good' :
    s >= 60 ? 'Satisfactory' :
    s >= 40 ? 'Needs_Improvement' : 'Poor';
}

return [{ json: { ...buildData, rubric_evaluation: rubricResult }}];

const data = $input.first().json;

// ── Early exit if session complete ──
if (data.session_complete) {
  return [{ json: { ...data, next_question: null, feedback_report: null } }];
}

const safeObject = (obj) => obj ?? {};
const safeArray  = (arr) => Array.isArray(arr) ? arr : [];

const session    = safeObject(data.updated_session);
const topic      = session.selected_topic ?? 'Java Basics';
const difficulty = session.current_difficulty ?? 'easy';
const profile    = safeObject(session.mastery_profile);
const evalResult = safeObject(data.evaluation_result);
const isCorrect  = evalResult.is_correct ?? false;

// ── Partial Correct + Weak Concepts ───────────────────────────
const isPartialCorrect = data.is_partial_correct || false;

const currentWeakConcepts = safeArray(data.weak_concepts);
const sessionHistory      = safeArray(session.session_history);

const lastEntry     = sessionHistory.length > 0
  ? sessionHistory[sessionHistory.length - 1]
  : null;

const lastWeakConc  = lastEntry
  ? safeArray(lastEntry.weak_concepts)
  : [];

const weakConcepts =
  currentWeakConcepts.length > 0
    ? currentWeakConcepts
    : lastWeakConc;

const hasWeakConcepts = weakConcepts.length > 0;

// ── Remediation State ─────────────────────────────────────────
const isRemediationMode    = session.remediation_mode || false;
const remediationQuestions = session.remediation_questions || 0;

const knowledgeGaps  = safeArray(profile.knowledge_gaps);

const topicDetails =
  knowledgeGaps.find(g => g.topic === topic) ?? {};

const misconceptions =
  safeArray(topicDetails.misconceptions);

const errorPatterns =
  safeArray(
    topicDetails.error_patterns ||
    topicDetails.observed_error_patterns ||
    []
  );

const askedQuestions =
  sessionHistory
    .map(h => h.question_text)
    .filter(Boolean);

const avoidSection =
  askedQuestions.length > 0
    ? `\nNEVER repeat these already-asked questions:\n${askedQuestions.slice(-8).join('\n')}`
    : '';

const topicScores   = safeObject(session.topic_scores);
const topicScoreObj = safeObject(topicScores[topic]);

const masteryScore =
  topicScoreObj.mastery_score ?? 0;

const questionsAsked =
  topicScoreObj.questions_asked ?? 0;

const consecutiveCorrect =
  session.consecutive_correct ?? 0;

const consecutiveWrong =
  session.consecutive_wrong ?? 0;

// ── Bloom's Taxonomy Levels ──────────────────────────────────
const bloomsLevels = {

  L1: {
    name: "Remembering (Bloom's L1)",
    difficulty: 'easy',
    question_type: 'mcq',
    instruction:
      "Generate an MCQ testing RECALL of facts, keywords, and syntax. 4 options A-D."
  },

  L2: {
    name: "Understanding (Bloom's L2)",
    difficulty: 'easy',
    question_type: 'mcq',
    instruction:
      "Generate an MCQ testing UNDERSTANDING of concepts. 4 options A-D."
  },

  L3: {
    name: "Applying (Bloom's L3)",
    difficulty: 'medium',
    question_type: 'code_completion',
    instruction:
      "Generate a Java CODE COMPLETION task with a code snippet."
  },

  L4: {
    name: "Analyzing (Bloom's L4)",
    difficulty: 'medium',
    question_type: 'code_tracing',
    instruction:
      "Generate a Java CODE TRACING problem where learner predicts execution/output."
  },

  L5: {
    name: "Evaluating (Bloom's L5)",
    difficulty: 'hard',
    question_type: 'debugging',
    instruction:
      "Generate a Java DEBUGGING challenge with intentional bugs."
  },

  L6: {
    name: "Creating (Bloom's L6)",
    difficulty: 'hard',
    question_type: 'coding_challenge',
    instruction:
      "Generate a Java CODING CHALLENGE requiring full implementation."
  }
};

function getDifficultyLevel(diff) {

  if (diff === 'easy')   return 'L1';
  if (diff === 'medium') return 'L3';
  if (diff === 'hard')   return 'L5';

  return 'L1';
}

function getNextBloomsLevel(
  currentDiff,
  isCorrect,
  consecCorrect,
  consecWrong,
  isPartial
) {

  const currentLevel =
    getDifficultyLevel(currentDiff);

  const levelOrder =
    ['L1','L2','L3','L4','L5','L6'];

  const currentIdx =
    levelOrder.indexOf(currentLevel);

  if (isCorrect) {

    // Move upward after 2 consecutive correct answers
    if (
      consecCorrect >= 2 &&
      currentIdx < levelOrder.length - 1
    ) {
      return levelOrder[currentIdx + 1];
    }

    return currentLevel;

  } else if (isPartial) {

    // Maintain same level for partial understanding
    return currentLevel;

  } else {

    // Step downward after incorrect answer
    if (
      consecWrong >= 1 &&
      currentIdx > 0
    ) {
      return levelOrder[currentIdx - 1];
    }

    return currentLevel;
  }
}

let promptText;
let nextDiff;

const misconceptionNote =
  misconceptions.length > 0
    ? `\nKnown misconceptions: ${misconceptions.slice(0,3).join(', ')}`
    : '';

const errorNote =
  errorPatterns.length > 0
    ? `\nError patterns: ${errorPatterns.slice(0,3).join(', ')}`
    : '';

// ── REMEDIATION MODE ──────────────────────────────────────────
if (isRemediationMode) {

  // ── VALIDATION RULE: Context-aware remediation type selection ─
  // Determine what the learner was doing BEFORE entering remediation
  // by reading the last few history entries' difficulty levels.
  // If learner was solving hard/medium problems and is partial-correct,
  // NEVER drop to recall MCQ — preserve conceptual continuity.

  const prevDifficulties = sessionHistory
    .slice(-3)
    .map(h => h.difficulty)
    .filter(Boolean);

  const wasSolvingHard   = prevDifficulties.includes('hard');
  const wasSolvingMedium = prevDifficulties.includes('medium') || wasSolvingHard;

  // CRITICAL VALIDATION:
  // If learner was at hard/medium AND had partial credit
  // → analytical remediation (NEVER recall MCQ)
  const needsAnalyticalRemediation = (
    (wasSolvingHard || wasSolvingMedium) && isPartialCorrect
  );

  // Context-aware question type selection
  // needsAnalyticalRemediation → code_tracing or code_completion always
  // Coming from easy + fully wrong → allowed to use structured MCQ briefly
  let remQuestionType, remBloomsLevel, remDifficulty;

  if (needsAnalyticalRemediation) {
    // Learner was doing hard/medium and has partial understanding
    // Preserve cognitive level — use analytical question types
    remDifficulty   = wasSolvingHard ? 'medium' : 'medium';
    remBloomsLevel  = "Analyzing (Bloom's L4) - REMEDIATION";
    remQuestionType = remediationQuestions < 3 ? 'code_tracing' : 'code_completion';

  } else {
    // Learner was at easy level or fully wrong at all levels
    // Allow gentle scaffolding: structured MCQ → code_tracing progression
    remDifficulty   = remediationQuestions < 2 ? 'easy' : 'medium';
    remBloomsLevel  = remediationQuestions < 2
      ? "Understanding (Bloom's L2) - REMEDIATION"
      : "Analyzing (Bloom's L4) - REMEDIATION";
    // Even for easy path: use MCQ only for first 1 question, then tracing
    remQuestionType = remediationQuestions < 1 ? 'mcq' : 'code_tracing';
  }

  const remConceptFocus =
    hasWeakConcepts
      ? `\nFOCUS specifically on these weak areas identified from the learner's last answer:\n${weakConcepts.slice(0,4).join('\n')}`
      : '';

  // Build remediation-specific instruction that preserves concept continuity
  let remInstructionDetail;

  if (needsAnalyticalRemediation) {
    remInstructionDetail = `
REMEDIATION TYPE: Analytical Scaffolded Remediation
REASON: Learner was solving ${wasSolvingHard ? 'hard' : 'medium'}-difficulty problems and showed partial understanding.

DO NOT generate:
- Simple recall questions ("What is the purpose of X?")
- Terminology-only MCQs
- Beginner-level definition questions

INSTEAD generate one of:
- Guided code execution tracing (trace through recursive calls step by step)
- Scaffolded code analysis (partially completed recursive logic to analyze)
- Structured code completion (fill in the specific missing logic related to the weak concept)
- Identify incorrect recursive branch or base condition error
- Fix a broken recursion structure that matches the learner's weak concept

CONCEPTUAL CONTINUITY RULE:
The question MUST stay connected to the learner's previous work.
If learner was working on recursion → generate recursion tracing.
If learner was working on sorting → generate sorting trace.
If learner was working on data structures → generate structural analysis.
NEVER jump to an unrelated simpler topic.`;
  } else {
    remInstructionDetail = `
REMEDIATION TYPE: Gentle Scaffolded Support
REASON: Learner needs foundational reinforcement.

Generate a guided analytical question:
- Use simple but complete Java code snippet
- Focus on the specific weak concept identified
- Include execution tracing elements
- Reinforce the concept step by step
DO NOT generate pure terminology recall questions.`;
  }

  promptText = `You are an expert adaptive Java tutor.

Generate EXACTLY ONE remediation question.

STRICT RULES:
- difficulty MUST be exactly "${remDifficulty}"
- blooms_level MUST be exactly "${remBloomsLevel}"
- question_type MUST be exactly "${remQuestionType}"
- Return ONLY valid JSON
- No markdown
- No explanations outside JSON
- Ensure JSON is COMPLETE and properly closed
- question_id MUST be exactly "PLACEHOLDER"
- Do NOT generate or invent a real question ID; n8n generates it after parsing

IMPORTANT MCQ RULES (only if question_type is mcq):
- options MUST be: { "A":"...", "B":"...", "C":"...", "D":"..." }
- correct_answer MUST contain ONLY: "A", "B", "C", or "D"
- NEVER place explanations, reasoning, or sentences inside correct_answer

IMPORTANT NON-MCQ RULES (for code_tracing, code_completion, debugging):
- options MUST be null
- correct_answer should contain: actual output, expected code, or null
- evaluation_criteria must explain how the answer will be evaluated
${remInstructionDetail}

TOPIC: ${topic}
MISCONCEPTIONS:${misconceptionNote}
ERRORS:${errorNote}
${remConceptFocus}

Generate REAL Java content only targeting the specific weak concepts above.
Maintain conceptual continuity with the learner's previous problem-solving work.

Return ONLY valid JSON.`;

  nextDiff = remDifficulty;

} else {

  // ── NORMAL ADAPTIVE FLOW ───────────────────────────────────

  const nextLevel = getNextBloomsLevel(
    difficulty,
    isCorrect,
    consecutiveCorrect,
    consecutiveWrong,
    isPartialCorrect
  );

  const bloom = bloomsLevels[nextLevel];

  nextDiff = bloom.difficulty;

  let conceptFocusSection = '';

  if (hasWeakConcepts && !isCorrect) {

    conceptFocusSection = `
CONCEPT-LEVEL REMEDIATION REQUIRED:

The learner's last answer revealed these weak concepts:

${weakConcepts.slice(0,4).map((c,i) =>
  `${i+1}. ${c}`).join('\n')}

Do NOT generate a generic ${topic} question.
Target these specific weak concepts directly.
Use a different angle than previous questions.`;

  } else if (hasWeakConcepts && isPartialCorrect) {

    conceptFocusSection = `
PARTIAL UNDERSTANDING DETECTED:

Focus on these gaps:

${weakConcepts.slice(0,3).map((c,i) =>
  `${i+1}. ${c}`).join('\n')}

Maintain current cognitive level.
Deepen conceptual understanding.
Do NOT repeat previous question structure.`;
  }

  let adaptiveInstruction;

  if (isCorrect) {

    adaptiveInstruction =
      `Learner answered CORRECTLY (${consecutiveCorrect} consecutive correct answers).

Move toward ${bloom.name}.
Generate a MORE CHALLENGING question.`;

  } else if (isPartialCorrect) {

    adaptiveInstruction =
      `Learner gave a PARTIALLY CORRECT answer.

Maintain current Bloom level:
${bloom.name}

Target the weak concepts identified above.
Do NOT drop difficulty unnecessarily.`;

  } else {

    adaptiveInstruction =
      `Learner answered INCORRECTLY.

Provide scaffolded support using:
${bloom.name}

Keep same concept but use a different angle.
Do NOT repeat the same question.`;
  }

  // ✅ FIXED:
  // Includes code_tracing now

  let correctAnswerRule = '';

  if (
    [
      'coding_challenge',
      'debugging',
      'code_completion',
      'code_tracing'
    ].includes(bloom.question_type)
  ) {

    correctAnswerRule = `
- For ${bloom.question_type} questions:

  - options MUST be null

  - correct_answer MUST NOT be:
      "A", "B", "C", or "D"

  - correct_answer should contain:
      - actual output
      - expected code
      - debugging fix
      - or null

  - evaluation_criteria must explain how the answer will be evaluated`;
  }

  promptText = `You are an expert adaptive Java tutor using Bloom's Taxonomy.

Generate EXACTLY ONE adaptive Java assessment question.

STRICT RULES:
- difficulty MUST be exactly "${nextDiff}"
- blooms_level MUST be exactly "${bloom.name}"
- question_type MUST be exactly "${bloom.question_type}"
- Return ONLY valid JSON
- No markdown
- No explanations outside JSON
- Ensure JSON is COMPLETE and properly closed

IMPORTANT MCQ RULES:
- For MCQ questions:
  - options MUST be:
    {
      "A":"...",
      "B":"...",
      "C":"...",
      "D":"..."
    }

  - correct_answer MUST contain ONLY:
      "A", "B", "C", or "D"

  - NEVER place:
      - explanations
      - reasoning
      - full sentences
      - option text
      inside correct_answer

VALID:
"correct_answer":"A"

INVALID:
"correct_answer":"Because synchronization prevents race conditions"

IMPORTANT NON-MCQ RULES:
- For NON-MCQ questions:
  - options MUST be null

  - correct_answer MUST NOT be:
      "A", "B", "C", or "D"

  - correct_answer should contain:
      - actual output
      - expected code
      - debugging fix
      - or null

VALID:
"correct_answer":"31"

VALID:
"correct_answer":"public int sum(int a,int b)"

INVALID:
"correct_answer":"B"

${correctAnswerRule}

LEARNER STATE:
- Topic: ${topic}
- Mastery: ${masteryScore}%
- Questions Asked: ${questionsAsked}
- Consecutive Correct: ${consecutiveCorrect}
- Consecutive Wrong: ${consecutiveWrong}
${misconceptionNote}
${errorNote}
${conceptFocusSection}

ADAPTIVE INSTRUCTION:
${adaptiveInstruction}

${avoidSection}

QUESTION INSTRUCTION:
${bloom.instruction}

Required JSON structure:
{
  "question_id":"PLACEHOLDER",
  "topic":"${topic}",
  "difficulty":"${nextDiff}",
  "blooms_level":"${bloom.name}",
  "question_type":"${bloom.question_type}",
  "question_text":"Actual adaptive question",
  "code_snippet":"Java code if required, otherwise null",

  "options": ${
    bloom.question_type === 'mcq'
      ? '{"A":"...","B":"...","C":"...","D":"..."}'
      : 'null'
  },

  "correct_answer": ${
    bloom.question_type === 'mcq'
      ? '"A"'
      : '"actual expected output or null"'
  },

  "evaluation_criteria":"Specific evaluation criteria",
  "hints":[
    "Hint targeting the weak concept",
    "More specific hint"
  ]
}`;
}

// ── Stable Ollama Payload ────────────────────────────────────
const ollamaPayload = {
  model: "gemma4:latest",
  prompt: promptText,
  stream: false,
  format: "json",
  options: {
    temperature: 0.1,
    num_predict: 1100,
    num_ctx: 4096,
    keep_alive: '10m'
  }
