return [{
  json: {
    ...data,
    next_question_prompt: promptText,
    ollama_payload: ollamaPayload,
    feedback_report: null,
    is_remediation: isRemediationMode,
    is_partial_correct: isPartialCorrect,
    weak_concepts: weakConcepts
  }
}];

// ============================================================
// Repair Truncated JSON - Next Question
// SAFETY NET: Ollama sometimes hits num_predict before finishing
// the JSON object (done_reason: "length"), leaving an unterminated
// string / unclosed braces / a dangling "key": with no value / a
// trailing comma. This tries a normal parse first, and only if
// that fails, walks the text as a mini state machine and repairs
// it so the run doesn't crash. Does not change the Ollama call or
// the Parse node.
// ============================================================
const data = $input.first().json;
const raw = data.response || '';

function tryParse(text) {
  try { return { ok: true, value: JSON.parse(text) }; }
  catch (e) { return { ok: false, error: e.message }; }
}

// Scans the text and returns { stack, inString } describing what is
// still "open" at the end of the string (used both to decide what
// needs closing, and to find where a dangling ":" value would start).
function scanState(text) {
  const stack = [];
  let inString = false;
  let escaped = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) { escaped = false; }
      else if (ch === '\\') { escaped = true; }
      else if (ch === '"') { inString = false; }
      continue;
    }
    if (ch === '"') { inString = true; continue; }
    if (ch === '{' || ch === '[') { stack.push(ch); continue; }
    if (ch === '}' || ch === ']') { stack.pop(); continue; }
  }
  return { stack, inString };
}

// Was the last colon (outside any string) followed by the start of a
// value, or does the text end with "key": <nothing>?
function danglingKeyColonIndex(text) {
  let inString = false;
  let escaped = false;
  let lastColon = -1;
  let valueStarted = true;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) { escaped = false; }
      else if (ch === '\\') { escaped = true; }
      else if (ch === '"') { inString = false; if (!valueStarted) valueStarted = true; }
      continue;
    }
    if (ch === '"') { inString = true; if (lastColon !== -1 && !valueStarted) { /* value begins */ } continue; }
    if (ch === ':') { lastColon = i; valueStarted = false; continue; }
    if (ch === ',' || ch === '{' || ch === '[') { valueStarted = true; continue; }
    if (/\S/.test(ch)) { valueStarted = true; }
  }
  return valueStarted ? -1 : lastColon;
}

function closeOpenStructures(text) {
  const { stack, inString } = scanState(text);
  let out = text;
  if (inString) out += '"';
  for (let i = stack.length - 1; i >= 0; i--) {
    out += (stack[i] === '{') ? '}' : ']';
  }
  return out;
}

function repairTruncatedJson(original) {
  let s = original;

  // 1. If we're cut off mid-string, terminate it so the tokenizer
  //    can make sense of everything that follows structurally.
  const { inString } = scanState(s);
  if (inString) s += '"';

  // 2. If the text ends with a key that never got a value
  //    (e.g. `..."hints":`  or  `..."correct_answer": `), drop that
  //    incomplete "key": entirely rather than guessing a value.
  const danglingIdx = danglingKeyColonIndex(s);
  if (danglingIdx !== -1) {
    let cut = s.lastIndexOf('"', danglingIdx - 1); // closing quote of key
    cut = s.lastIndexOf('"', cut - 1);              // opening quote of key
    if (cut !== -1) s = s.slice(0, cut);
  }

  // 3. Repair an obviously incomplete trailing literal or number,
  //    e.g. "tru", "fals", "nul", "12.", a lone "-".
  s = s.replace(/:\s*(t|tr|tru|f|fa|fal|fals|n|nu|nul)\s*$/i, ': null');
  s = s.replace(/([\[,]\s*)(t|tr|tru|f|fa|fal|fals|n|nu|nul)\s*$/i, '$1null');
  s = s.replace(/(-?\d+)\.\s*$/, '$1');
  s = s.replace(/-\s*$/, '');

  // 4. Strip any trailing comma (with trailing whitespace) — nothing
  //    valid follows it, and a comma right before a closing bracket
  //    is invalid JSON.
  s = s.replace(/,\s*$/, '');

  // 5. Close every brace/bracket (and string, if step 1 missed a
  //    fresh one opened by the trims above) still open at this point.
  s = closeOpenStructures(s);

  return s;
}

const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let result = tryParse(cleaned);

if (!result.ok) {
  const repaired = repairTruncatedJson(cleaned);
  result = tryParse(repaired);

  if (result.ok) {
    return [{ json: {
      ...data,
      response: repaired,
      json_was_truncated: true,
      json_repair_applied: true,
      original_truncated_response: raw
    }}];
  }

  // Repair failed too — pass through untouched so the existing
  // Parse node's own fallback/error handling still runs exactly
  // as it did before this node was added.
  return [{ json: {
    ...data,
    json_was_truncated: true,
    json_repair_applied: false,
    json_repair_error: result.error,
    json_repair_attempt: repaired
  }}];
}

// Was already valid JSON — pass through unchanged.
return [{ json: { ...data, json_was_truncated: false } }];

// ============================================================
// NODE: Build Sandbox Execution Payload
// PURPOSE: For code_completion / coding_challenge questions,
// wrap the learner's submitted Java code into a compilable
// source file and build the Judge0 execution request.
// This node ONLY runs on the true branch of
// "IF - Is Code Sandbox Question?" — MCQ / conceptual questions
// never reach this node, so nothing else in the workflow changes.
// ============================================================

const data = $input.first().json;
const question = data.question || {};
const submittedAnswer = data.submittedAnswer || '';

let studentCode = String(submittedAnswer).trim();

// Judge0's Java runner compiles the file as "Main.java" and expects
// a "public class Main" entry point. Learners/the LLM may submit a
// full class, a partial snippet, or just a method body — normalize
// all of these into a single runnable Main class.
const hasClass = /\bclass\s+\w+/.test(studentCode);
const hasMain  = /public\s+static\s+void\s+main\s*\(/.test(studentCode);

let sourceCode;
if (studentCode.length === 0) {
  sourceCode = null; // nothing submitted — skip execution entirely
} else if (hasClass) {
  // Force the public class name to "Main" so Judge0 compiles it
  // regardless of what name the learner/model used.
  sourceCode = studentCode.replace(/\bclass\s+\w+/, 'class Main');
  // If there's a class but no main(), submit as-is — Judge0 will
  // return a compile error, which is valid signal for the evaluator.
} else {
  sourceCode =
`public class Main {
  public static void main(String[] args) throws Exception {
${studentCode}
  }
}`;
}

const judge0Payload = sourceCode ? {
  language_id: 62, // Java (OpenJDK 13.0.1) on Judge0 CE
  source_code: sourceCode,
  stdin: question.stdin || '',
  cpu_time_limit: 5,
  memory_limit: 128000,
  wall_time_limit: 10
} : null;

return [{ json: {
  ...data,
  sandbox_source_code: sourceCode,
  judge0_payload: judge0Payload
}}];

// ============================================================
// NODE: Parse Sandbox Execution Result
// PURPOSE: Normalize the Judge0 response into a compact
// sandbox_result object. This is consumed by "Build Evaluation
// Prompt" and "Build Rubric Evaluation Prompt" (as grounding
// evidence for the LLM) and is also returned to the frontend so
// it can render a console/output panel for code questions.
// ============================================================

const buildData = $('Build Sandbox Execution Payload').first().json;
const judge0Response = $input.first().json;

function decode(v) {
  if (v === null || v === undefined) return null;
  return String(v);
}

let sandboxResult;

if (!buildData.judge0_payload) {
  sandboxResult = {
    attempted: false,
    reason: 'No code submitted to execute.'
  };
} else if (judge0Response && judge0Response.status) {
  const statusId = judge0Response.status.id;
  const statusDesc = judge0Response.status.description || 'Unknown';
  sandboxResult = {
    attempted: true,
    compiled: !judge0Response.compile_output,
    // Judge0 status id 3 = "Accepted" (ran without compile/runtime error).
    executed_successfully: statusId === 3,
    status: statusDesc,
    stdout: decode(judge0Response.stdout),
    stderr: decode(judge0Response.stderr),
    compile_output: decode(judge0Response.compile_output),
    time_seconds: judge0Response.time || null,
    memory_kb: judge0Response.memory || null,
    source_code_run: buildData.sandbox_source_code
  };
} else {
  // Sandbox unreachable / malformed response — never fail the whole
  // evaluation. Mark the sandbox as unavailable and let the LLM
  // evaluator fall back to reading the submitted text, same as before
  // sandbox support existed.
  sandboxResult = {
    attempted: true,
    executed_successfully: null,
    status: 'sandbox_unavailable',
    reason: 'Could not reach the code execution sandbox.',
    stdout: null,
    stderr: null,
    compile_output: null,
    source_code_run: buildData.sandbox_source_code
  };
}

return [{ json: { ...buildData, sandbox_result: sandboxResult } }];

// ============================================================
// NODE: Build Run-Code Sandbox Payload
// PURPOSE: Powers an optional "Run Code" / "Test" button the
// frontend can offer on code_completion & coding_challenge
// questions BEFORE the learner submits their final answer.
// This is a pure preview — it never touches scoring, mastery,
// or MongoDB, and is fully independent of the submit-answer flow.
//
// Expects POST body: { session_id, question_id, code, stdin? }
// ============================================================

const body = $input.first().json.body || {};

if (body.code === undefined || body.code === null || String(body.code).trim() === '') {
  throw new Error('Missing code to run');
}

let studentCode = String(body.code).trim();
const hasClass = /\bclass\s+\w+/.test(studentCode);

let sourceCode;
if (hasClass) {
  sourceCode = studentCode.replace(/\bclass\s+\w+/, 'class Main');
} else {
  sourceCode =
`public class Main {
  public static void main(String[] args) throws Exception {
${studentCode}
  }
}`;
}

const judge0Payload = {
  language_id: 62, // Java (OpenJDK 13.0.1) on Judge0 CE
  source_code: sourceCode,
  stdin: body.stdin || '',
  cpu_time_limit: 5,
  memory_limit: 128000,
  wall_time_limit: 10
};

return [{ json: {
  session_id: body.session_id || null,
  question_id: body.question_id || null,
  sandbox_source_code: sourceCode,
  judge0_payload: judge0Payload
}}];

// ============================================================
// NODE: Parse Run Code Result
// PURPOSE: Normalize the Judge0 response for the "Run Code"
// preview endpoint, returned directly to the frontend.
// ============================================================

const buildData = $('Build Run-Code Sandbox Payload').first().json;
const judge0Response = $input.first().json;

function decode(v) {
  if (v === null || v === undefined) return null;
  return String(v);
}

let result;
if (judge0Response && judge0Response.status) {
  result = {
    compiled: !judge0Response.compile_output,
    executed_successfully: judge0Response.status.id === 3,
    status: judge0Response.status.description || 'Unknown',
    stdout: decode(judge0Response.stdout),
    stderr: decode(judge0Response.stderr),
    compile_output: decode(judge0Response.compile_output),
    time_seconds: judge0Response.time || null,
    memory_kb: judge0Response.memory || null
  };
} else {
  result = {
    compiled: false,
    executed_successfully: false,
    status: 'sandbox_unavailable',
    stdout: null,
    stderr: null,
    compile_output: null
  };
}

return [{ json: { ...buildData, run_result: result } }];

const docs = $input.all().map(i => i?.json || {}).filter(x => x && (x.current_question || x.question_id));
const expectedSession = String($('Ensure Next Question Fields').first().json.session_id || '').trim();
const expectedQuestion = String($('Ensure Next Question Fields').first().json.question_id || '').trim();
const match = docs.find(d => String(d.session_id || '').trim() === expectedSession && String(d.question_id || '').trim() === expectedQuestion);
if (!match) {
  throw new Error(`CRITICAL: Next question was generated but was NOT persisted in ame_questions. session_id=${expectedSession}, question_id=${expectedQuestion}. The workflow will not return an unsaved question to the learner.`);
}
return [{ json: { save_verified: true, session_id: expectedSession, question_id: expectedQuestion, verified_question: match.current_question } }];
